PRAGMA journal_mode = WAL;
CREATE TABLE IF NOT EXISTS index_metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agents (id INTEGER PRIMARY KEY, kind TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS hosts (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, host_id INTEGER NOT NULL REFERENCES hosts(id), os_user TEXT NOT NULL, UNIQUE(host_id, os_user));
CREATE TABLE IF NOT EXISTS agent_instances (id INTEGER PRIMARY KEY, agent_id INTEGER NOT NULL REFERENCES agents(id), user_id INTEGER NOT NULL REFERENCES users(id), source_home TEXT NOT NULL UNIQUE, source_key TEXT);
CREATE TABLE IF NOT EXISTS ingest_runs (id INTEGER PRIMARY KEY, started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, finished_at TEXT, status TEXT NOT NULL, files_seen INTEGER NOT NULL DEFAULT 0, errors INTEGER NOT NULL DEFAULT 0, source_layout TEXT NOT NULL DEFAULT 'host-user', failure_reason TEXT);
CREATE TABLE IF NOT EXISTS source_files (id INTEGER PRIMARY KEY, instance_id INTEGER NOT NULL REFERENCES agent_instances(id), ingest_run_id INTEGER NOT NULL REFERENCES ingest_runs(id), path TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, size_bytes INTEGER, modified_at TEXT, observed_at TEXT, parse_status TEXT NOT NULL, parse_error TEXT, content_hash TEXT, parser_version INTEGER);
CREATE TABLE IF NOT EXISTS sessions (id INTEGER PRIMARY KEY, instance_id INTEGER NOT NULL REFERENCES agent_instances(id), source_file_id INTEGER REFERENCES source_files(id), external_id TEXT NOT NULL, stable_id TEXT, started_at TEXT, ended_at TEXT, cwd TEXT, model TEXT, status TEXT, title TEXT, derived_title TEXT, raw_metadata TEXT, UNIQUE(instance_id, external_id));
CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, sequence INTEGER NOT NULL, timestamp TEXT, role TEXT NOT NULL, content TEXT NOT NULL, raw_json TEXT, UNIQUE(session_id, sequence));
CREATE VIRTUAL TABLE IF NOT EXISTS message_search USING fts5(content, session_id UNINDEXED, sequence UNINDEXED, role UNINDEXED, content='messages', content_rowid='id', tokenize='unicode61');
CREATE TABLE IF NOT EXISTS tool_calls (id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, sequence INTEGER NOT NULL, timestamp TEXT, call_id TEXT, tool_name TEXT, arguments TEXT, output TEXT, status TEXT, raw_json TEXT, kind TEXT NOT NULL DEFAULT 'tool', turn_ordinal INTEGER);
CREATE TABLE IF NOT EXISTS tool_results (id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, source_sequence INTEGER NOT NULL, sequence_known INTEGER NOT NULL DEFAULT 1, timestamp TEXT, call_id TEXT, tool_call_id INTEGER REFERENCES tool_calls(id) ON DELETE CASCADE, output TEXT, outcome TEXT NOT NULL, raw_json TEXT, turn_ordinal INTEGER);
CREATE TRIGGER IF NOT EXISTS tool_results_pair AFTER INSERT ON tool_results WHEN new.tool_call_id IS NOT NULL BEGIN
  UPDATE tool_calls SET output=new.output,status=CASE WHEN new.outcome='failed' THEN 'failed' ELSE 'complete' END WHERE id=new.tool_call_id;
END;
CREATE TABLE IF NOT EXISTS usage_events (id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, source_sequence INTEGER, sequence_known INTEGER NOT NULL DEFAULT 0, timestamp TEXT, input_tokens INTEGER, output_tokens INTEGER, cached_input_tokens INTEGER, reasoning_output_tokens INTEGER, total_tokens INTEGER, per_turn_input_tokens INTEGER, per_turn_output_tokens INTEGER, per_turn_cached_input_tokens INTEGER, per_turn_reasoning_output_tokens INTEGER, per_turn_total_tokens INTEGER, delta_input_tokens INTEGER, delta_output_tokens INTEGER, delta_cached_input_tokens INTEGER, delta_reasoning_output_tokens INTEGER, delta_total_tokens INTEGER, cumulative_present INTEGER NOT NULL DEFAULT 0, per_turn_present INTEGER NOT NULL DEFAULT 0, is_duplicate INTEGER NOT NULL DEFAULT 0, has_reset INTEGER NOT NULL DEFAULT 0, has_missing INTEGER NOT NULL DEFAULT 0, has_inconsistent INTEGER NOT NULL DEFAULT 0, context_window INTEGER, context_tokens INTEGER, rate_limit_id TEXT, rate_limit_name TEXT, primary_used_percent REAL, primary_window_minutes INTEGER, primary_resets_at INTEGER, primary_resets_in_seconds INTEGER, secondary_used_percent REAL, secondary_window_minutes INTEGER, secondary_resets_at INTEGER, secondary_resets_in_seconds INTEGER, plan_type TEXT, rate_limit_reached_type TEXT, raw_json TEXT);
CREATE TABLE IF NOT EXISTS session_usage (session_id INTEGER PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, input_tokens INTEGER, output_tokens INTEGER, cached_input_tokens INTEGER, reasoning_output_tokens INTEGER, total_tokens INTEGER, snapshot_count INTEGER NOT NULL, per_turn_observation_count INTEGER NOT NULL, reset_count INTEGER NOT NULL, duplicate_count INTEGER NOT NULL, missing_count INTEGER NOT NULL, inconsistent_count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS turns (id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, ordinal INTEGER NOT NULL, turn_id TEXT, start_sequence INTEGER, start_timestamp TEXT, start_kind TEXT NOT NULL, end_sequence INTEGER, end_timestamp TEXT, outcome TEXT NOT NULL, resumed INTEGER NOT NULL DEFAULT 0, requested_model TEXT, requested_model_sequence INTEGER, observed_model TEXT, observed_model_sequence INTEGER, UNIQUE(session_id, ordinal));
CREATE TABLE IF NOT EXISTS turn_events (id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, turn_ordinal INTEGER, source_sequence INTEGER NOT NULL, timestamp TEXT, kind TEXT NOT NULL, turn_id TEXT, requested_model TEXT, served_model TEXT, is_resumption INTEGER NOT NULL DEFAULT 0, is_model_change INTEGER NOT NULL DEFAULT 0, raw_json TEXT, UNIQUE(session_id, source_sequence));
CREATE INDEX IF NOT EXISTS idx_sessions_started ON sessions(started_at DESC);
CREATE INDEX IF NOT EXISTS idx_sessions_started_id ON sessions(started_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_messages_session ON messages(session_id, sequence);
CREATE INDEX IF NOT EXISTS idx_sessions_source_file ON sessions(source_file_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_tool_calls_session_sequence ON tool_calls(session_id, sequence);
CREATE INDEX IF NOT EXISTS idx_tool_calls_pair ON tool_calls(session_id, call_id, sequence DESC);
CREATE UNIQUE INDEX IF NOT EXISTS idx_tool_results_session_sequence ON tool_results(session_id, source_sequence);
CREATE INDEX IF NOT EXISTS idx_tool_results_call ON tool_results(tool_call_id, source_sequence);
CREATE INDEX IF NOT EXISTS idx_usage_events_session ON usage_events(session_id);
CREATE INDEX IF NOT EXISTS idx_turns_session ON turns(session_id, ordinal);
CREATE INDEX IF NOT EXISTS idx_turn_events_session ON turn_events(session_id, source_sequence);

CREATE TABLE IF NOT EXISTS redaction_audit (ingest_run_id INTEGER NOT NULL REFERENCES ingest_runs(id), source_key TEXT NOT NULL, policy_version TEXT NOT NULL, rule_id TEXT NOT NULL, replacement_count INTEGER NOT NULL);
